import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_rate_none_counts_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None),
                              event("c", 1, False)]) == 1 / 3
    assert monitor_flag_rate([]) == 0.0
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0


def test_pooled_rate_weights_transcripts_not_groups():
    groups = {"small": [event("a", 1, True)],
              "large": [event(str(i), 1, False) for i in range(3)],
              "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 3), (2, 5), (3, 6), (8, 6)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected
    assert flags_in_window([], days) == 0


def test_parse_flags_whitespace_and_skipped_lines():
    lines = ["  # comment, even with commas\n", "\n", "  \t  ",
             " x , 3 , 1 ", " y, -2, 0", "z,0,  "]
    assert parse_transcript_log(lines) == [event("x", 3, True),
                                           event("y", -2, False),
                                           event("z", 0, None)]


@pytest.mark.parametrize("bad_line", ["one,two", "a,1,1,extra", "a,no,1", "a,1,yes"])
def test_parse_errors_report_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# comment", " ", "a,1,0", bad_line])


def test_dedupe_last_duplicate_id_wins_then_sorts():
    first = event("b", 1, True)
    latest = event("b", 3, None)
    a = event("a", 3, False)
    c = event("c", 2, True)
    assert dedupe_transcripts([first, a, c, latest]) == [c, a, latest]
    assert dedupe_transcripts([]) == []


def test_daily_counts_include_gaps_and_ignore_outside_range():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 2, None), event("e", 3, False), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_summary_uses_calendar_days_pooled_rate_and_nonempty_groups():
    groups = {"a": [event("a", 1, True)],
              "b": [event("b", 4, True), event("c", 5, False)], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 3)["recent"] == 1
    assert monitor_summary(groups, 4)["recent"] == 1
    assert monitor_summary(groups, 5)["recent"] == 2
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 1) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_exclude_empty_and_break_ties_by_name():
    groups = {"z": [event("z", 1, True)], "empty": [],
              "a": [event("a", 1, True)], "b": [event("b", 1, False)]}
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_sorted_with_empty_as_none():
    groups = {"z": [], "b": [event("b", 1, False)], "a": [event("a", 1, True)]}
    rates = flag_rate_by_group(groups)
    assert list(rates) == ["a", "b", "z"]
    assert rates == {"a": 1.0, "b": 0.0, "z": None}


@pytest.mark.parametrize("counts, expected", [([], 0), ([0, -1, 0], 0),
                                               ([1, 2, 0, 3, -1, 4], 2),
                                               ([0, 1, 2, 3], 3)])
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected

